begin;
create temp table audit_results(label text, expected text, observed text, passed boolean);
grant all on audit_results to authenticated;
create temp table audit_apps(id uuid,actor uuid,event_id uuid);
grant all on audit_apps to authenticated;
create function pg_temp.probe(label text, statement text, expected text default 'true') returns void language plpgsql as $$
declare observed text;
begin
 begin execute statement into observed; exception when others then observed := SQLSTATE || ': ' || SQLERRM; end;
 insert into audit_results values(label,expected,observed,coalesce(observed=expected or observed like expected||': %',false));
end $$;
